//! 🌐️ Fenestration validation inspects each original point and host edge before the shared owned-field producer runs.
use super::*;
use crate::snapshot::state::{StateFenestration,StateSurface};
/// 📐️ The authored geometry engine supplies its defining edge sum, normalization and plane tolerance.
pub trait OriginalFenestrationPlane:Send+Sync+'static{const TOLERANCE:f64;fn accumulate(sum:&mut[f64;3],a:[f64;3],b:[f64;3]);fn normal(sum:[f64;3])->[f64;3];}
pub struct FenestrationPlaneValidation<S:OriginalFenestrationPlane>{input:Option<RetainedCloneBinding>,original:Option<RetainedCloneBinding>,row:Option<RetainedCloneBinding>,body:Option<usize>,lookup:Option<Box<RetainedEntityLookup<StateSurface>>>,host:Option<RetainedOwnedProjection<StateSurface>>,offset:usize,sum:[f64;3],normal:[f64;3],result:Option<Option<RowOutcome>>,phase:u8,closing:bool,marker:std::marker::PhantomData<S>}
impl<S:OriginalFenestrationPlane> FenestrationPlaneValidation<S>{pub fn new()->Self{Self{input:None,original:None,row:None,body:None,lookup:None,host:None,offset:0,sum:[0.0;3],normal:[0.0;3],result:None,phase:0,closing:false,marker:Default::default()}}fn check(&self,i:RetainedCloneRef<'_,Vec<[f64;3]>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,r:RetainedCloneRef<'_,StateFenestration>)->Result<(),ValueError>{i.check_binding(&self.input)?;o.check_binding(&self.original)?;r.check_binding(&self.row)?;Ok(())}fn finish(&mut self,result:Option<RowOutcome>){self.result=Some(result);self.phase=99;}}
impl<S:OriginalFenestrationPlane> OwnedRowValidation<Vec<[f64;3]>,StateFenestration> for FenestrationPlaneValidation<S>{
 fn demand(&self,i:RetainedCloneRef<'_,Vec<[f64;3]>>,_:RetainedCloneRef<'_,u32>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,r:RetainedCloneRef<'_,StateFenestration>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.result.is_some()||self.body.is_some_and(|v|v!=body){return Err(invalid());}self.check(i,o,r)?;match self.phase{0=>nested(scalar(i.binding_copy_bytes()+size_of::<usize>()),1),1=>nested(scalar(r.binding_copy_bytes()),1),2=>nested(scalar(o.binding_copy_bytes()),1),3=>Ok(scalar(4*size_of::<usize>()+2)),4=>Ok(scalar(2*size_of::<[f64;3]>()+2*size_of::<usize>()+2)),5=>Ok(birth::<RetainedEntityLookup<StateSurface>>()),6=>nested(self.lookup.as_ref().ok_or_else(invalid)?.demand(o.project(0,|s|&s.model.geometry.get().surfaces),r.project(0,|r|&r.surface_id.0))?,1),7=>if self.lookup.as_ref().ok_or_else(invalid)?.result()==Some(None){Ok(scalar(2))}else{nested(self.lookup.as_ref().ok_or_else(invalid)?.take_demand()?,2*size_of::<Option<RetainedOwnedProjection<StateSurface>>>()+1)},8=>cursor_demand(&self.lookup,body),9=>Ok(scalar(6*size_of::<[f64;3]>()+4*size_of::<usize>()+1)),10=>Ok(scalar(4*size_of::<[f64;3]>()+2*size_of::<usize>()+1)),11=>Ok(scalar(6*size_of::<[f64;3]>()+2*size_of::<usize>()+2)),_=>Err(invalid())}}
 fn advance(&mut self,i:RetainedCloneRef<'_,Vec<[f64;3]>>,key:RetainedCloneRef<'_,u32>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,r:RetainedCloneRef<'_,StateFenestration>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(i,key,o,r,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);self.body=Some(body);match self.phase{0=>{p=add(i.bind(&mut self.input,child(g,1+size_of::<usize>()))?.ok_or_else(invalid)?,1+size_of::<usize>())?;self.phase=1;},1=>{p=add(r.bind(&mut self.row,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{p=add(o.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=3;},3=>{if i.get().is_empty(){self.finish(None);}else if i.get().len()<3{self.finish(Some(RowOutcome::Invalid));}else{self.phase=4;}},4=>{if self.offset==i.get().len(){self.offset=0;self.phase=5;}else{let point=i.get()[self.offset];if !point[0].is_finite()||!point[1].is_finite()||!point[2].is_finite(){self.finish(Some(RowOutcome::Invalid));}else{self.offset+=1;}}},5=>{self.lookup=Some(Box::new(RetainedEntityLookup::new()));self.phase=6;},6=>{let lookup=self.lookup.as_mut().ok_or_else(invalid)?;p=add(lookup.advance(o.project(0,|s|&s.model.geometry.get().surfaces),r.project(0,|r|&r.surface_id.0),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if lookup.result().is_some(){self.phase=7;}},7=>{let lookup=self.lookup.as_mut().ok_or_else(invalid)?;if lookup.result()==Some(None){self.finish(None);}else{let extra=2*size_of::<Option<RetainedOwnedProjection<StateSurface>>>()+1;let(host,paid)=lookup.take(child(g,extra)).map_err(|e|tag(e,extra))?.ok_or_else(invalid)?;self.host=Some(host);self.phase=8;lookup.begin_close();p=add(paid,extra)?;}},8=>{p=close_cursor(&mut self.lookup,g)?;if self.lookup.is_none(){self.phase=9;}},9=>{let host=self.host.as_ref().ok_or_else(invalid)?.borrow()?;let points=host.get().vertices_m.get();if points.len()<3{self.finish(None);}else if self.offset==points.len(){self.phase=10;}else{S::accumulate(&mut self.sum,points[self.offset],points[(self.offset+1)%points.len()]);self.offset+=1;}},10=>{self.normal=S::normal(self.sum);self.offset=0;if self.normal[0].abs()+self.normal[1].abs()+self.normal[2].abs()<1e-12{self.finish(None);}else{self.phase=11;}},11=>{if self.offset==i.get().len(){self.finish(None);}else{let host=self.host.as_ref().ok_or_else(invalid)?.borrow()?;let anchor=host.get().vertices_m.get()[0];let v=i.get()[self.offset];let n=self.normal;let distance=((v[0]-anchor[0])*n[0]+(v[1]-anchor[1])*n[1]+(v[2]-anchor[2])*n[2]).abs();if distance<=S::TOLERANCE{self.offset+=1;}else{self.finish(Some(RowOutcome::InvalidContext));}}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original fenestration host plane")?;Ok(if self.result.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<Option<RowOutcome>>{self.result}fn begin_close(&mut self){self.closing=true;if let Some(l)=self.lookup.as_mut(){l.begin_close();}}
}
impl<S:OriginalFenestrationPlane> CursorClose for FenestrationPlaneValidation<S>{fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}let body=self.body.unwrap_or(body);if self.lookup.is_some(){return cursor_demand(&self.lookup,body);}if let Some(host)=self.host.as_ref(){return if host.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedOwnedProjection<StateSurface>>>()))}else{host.close_demand(body)};}RetainedCloneBinding::close_demand(if self.input.is_some(){&self.input}else if self.row.is_some(){&self.row}else{&self.original},body)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(self.body.unwrap_or(g.maximum_copy_bytes))?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..g};if self.lookup.is_some(){return close_cursor(&mut self.lookup,g).map(RetainedCloneStep::Progress);}if let Some(host)=self.host.as_mut(){if host.terminal_is_empty(){drop(self.host.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return host.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}let s=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else if self.row.is_some(){&mut self.row}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}fn terminal_is_empty(&self)->bool{self.closing&&self.lookup.is_none()&&self.host.is_none()&&self.input.is_none()&&self.original.is_none()&&self.row.is_none()}}
impl<S:OriginalFenestrationPlane> Drop for FenestrationPlaneValidation<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original fenestration plane retains host or point source custody");}}
